const canvas = document.getElementById("view");
const ctx = canvas.getContext("2d");

let dpr = 1;

function resize() {
  dpr = Math.max(1, Math.floor(window.devicePixelRatio || 1));
  canvas.width = Math.floor(window.innerWidth * dpr);
  canvas.height = Math.floor(window.innerHeight * dpr);
  canvas.style.width = `${window.innerWidth}px`;
  canvas.style.height = `${window.innerHeight}px`;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
}
window.addEventListener("resize", resize);
resize();

function generateParticlesFromImage(img) {
  const off = document.createElement("canvas");
  const offCtx = off.getContext("2d");

  const DENSITY = 4; // 🔹 mais densidade

  off.width = img.width;
  off.height = img.height;

  offCtx.drawImage(img, 0, 0);

  const data = offCtx.getImageData(0, 0, img.width, img.height).data;
  const particles = [];

  for (let y = 0; y < img.height; y += DENSITY) {
    for (let x = 0; x < img.width; x += DENSITY) {
      const i = (y * img.width + x) * 4;
      const a = data[i + 3];

      if (a > 30) {
        particles.push({
          x,
          y,
          r: data[i],
          g: data[i + 1],
          b: data[i + 2],
          a: a / 255
        });
      }
    }
  }

  return {
    particles,
    width: img.width,
    height: img.height
  };
}

const img = new Image();
let model = null;

let startRequested = false;
let started = false;

let particles = [];
let stage = "idle";
let stageStartedAt = 0;
let lastFrameAt = 0;
let doneSignaled = false;

let rocketPoints = [];
let textPoints = [];
let textModelWidth = 1;
let textModelHeight = 1;

img.onload = () => {
  model = generateParticlesFromImage(img);
  rocketPoints = (model?.particles || []).map((p) => ({
    x: p.x,
    y: p.y,
    r: p.r,
    g: p.g,
    b: p.b,
    a: p.a
  }));

  if (startRequested) {
    internalStart();
  }
};
img.src = "data:image/png;base64,";

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function easeOutCubic(t) {
  const x = clamp(t, 0, 1);
  return 1 - Math.pow(1 - x, 3);
}

function shuffleInPlace(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

function buildTextPoints(text) {
  const off = document.createElement("canvas");
  const offCtx = off.getContext("2d");

  const fontSize = 200;
  const padding = 40;
  offCtx.font = `900 ${fontSize}px sans-serif`;

  const metrics = offCtx.measureText(text);
  const w = Math.ceil(metrics.width) + padding * 2;
  const h = fontSize + padding * 2;
  off.width = w;
  off.height = h;

  offCtx.clearRect(0, 0, w, h);
  offCtx.fillStyle = "#000";
  offCtx.fillRect(0, 0, w, h);
  offCtx.font = `900 ${fontSize}px sans-serif`;
  offCtx.textAlign = "center";
  offCtx.textBaseline = "middle";

  const gradient = offCtx.createLinearGradient(0, 0, w, 0);
  gradient.addColorStop(0, "#a855f7");
  gradient.addColorStop(0.55, "#7c3aed");
  gradient.addColorStop(1, "#c084fc");

  offCtx.fillStyle = gradient;
  offCtx.fillText(text, w / 2, h / 2 + 6);

  const data = offCtx.getImageData(0, 0, w, h).data;
  const points = [];
  const density = 4;

  for (let y = 0; y < h; y += density) {
    for (let x = 0; x < w; x += density) {
      const i = (y * w + x) * 4;
      const a = data[i + 3];
      if (a > 40) {
        points.push({
          x,
          y,
          r: data[i],
          g: data[i + 1],
          b: data[i + 2],
          a: a / 255
        });
      }
    }
  }

  return { points, width: w, height: h };
}

function mapPointToCanvas(point, modelW, modelH, scale, offsetX, offsetY) {
  return {
    x: offsetX + (point.x - modelW / 2) * scale,
    y: offsetY + (point.y - modelH / 2) * scale
  };
}

function getRocketLayout() {
  const w = window.innerWidth;
  const h = window.innerHeight;
  const scale = Math.min(w / (model?.width || 1), h / (model?.height || 1)) * 0.78;
  return { scale, cx: w / 2, cy: h / 2 };
}

function getTextLayout() {
  const w = window.innerWidth;
  const h = window.innerHeight;
  const scale = Math.min(w / textModelWidth, h / textModelHeight) * 0.72;
  return { scale, cx: w / 2, cy: h / 2 };
}

function ensureParticleCount(count) {
  const w = window.innerWidth;
  const h = window.innerHeight;
  while (particles.length < count) {
    particles.push({
      x: Math.random() * w,
      y: Math.random() * h,
      vx: (Math.random() - 0.5) * 2.4,
      vy: (Math.random() - 0.5) * 2.4,
      r: 180,
      g: 90,
      b: 247,
      a: 0.9,
      size: 2.1 + Math.random() * 0.8
    });
  }
  if (particles.length > count) {
    particles.length = count;
  }
}

function setStage(nextStage, now) {
  stage = nextStage;
  stageStartedAt = now;

  if (stage === "assembleRocket") {
    rocketPoints = shuffleInPlace(rocketPoints.slice());
    ensureParticleCount(rocketPoints.length);
    for (const p of particles) {
      p.vx *= 0.2;
      p.vy *= 0.2;
      p.a = 0.95;
    }
  }

  if (stage === "explode") {
    for (const p of particles) {
      const angle = Math.random() * Math.PI * 2;
      const speed = 4 + Math.random() * 7;
      p.vx = Math.cos(angle) * speed;
      p.vy = Math.sin(angle) * speed;
      p.a = 0.95;
    }
  }

  if (stage === "assembleText") {
    if (textPoints.length === 0) {
      const textModel = buildTextPoints("STARKAID");
      textPoints = textModel.points;
      textModelWidth = textModel.width;
      textModelHeight = textModel.height;
    }

    textPoints = shuffleInPlace(textPoints.slice());
    ensureParticleCount(textPoints.length);
    for (const p of particles) {
      p.vx *= 0.25;
      p.vy *= 0.25;
      p.a = 0.95;
    }
  }
}

function internalStart() {
  if (started) return;
  if (!model || rocketPoints.length === 0) return;

  started = true;
  doneSignaled = false;

  const w = window.innerWidth;
  const h = window.innerHeight;

  ensureParticleCount(Math.max(900, rocketPoints.length));
  for (const p of particles) {
    p.x = Math.random() * w;
    p.y = h + Math.random() * 60;
    p.vx = (Math.random() - 0.5) * 1.6;
    p.vy = -1 - Math.random() * 2.2;
    p.r = 180;
    p.g = 90;
    p.b = 247;
    p.a = 0.0;
  }

  const now = performance.now();
  lastFrameAt = now;
  setStage("assembleRocket", now);
  requestAnimationFrame(loop);
}

function loop(now) {
  const dtMs = clamp(now - lastFrameAt, 8, 34);
  lastFrameAt = now;
  const dt = dtMs / 16.67;

  const w = window.innerWidth;
  const h = window.innerHeight;

  ctx.clearRect(0, 0, w, h);

  if (stage === "assembleRocket") {
    const t = (now - stageStartedAt) / 2200;
    const k = 0.018 + 0.015 * easeOutCubic(t);
    const drag = 0.76;
    const layout = getRocketLayout();

    for (let i = 0; i < particles.length; i++) {
      const p = particles[i];
      const target = rocketPoints[i % rocketPoints.length];
      const mapped = mapPointToCanvas(target, model.width, model.height, layout.scale, layout.cx, layout.cy);

      const dx = mapped.x - p.x;
      const dy = mapped.y - p.y;
      p.vx = p.vx * drag + dx * k;
      p.vy = p.vy * drag + dy * k;
      p.x += p.vx * dt;
      p.y += p.vy * dt;

      p.r = target.r;
      p.g = target.g;
      p.b = target.b;
      p.a = clamp(p.a + 0.035 * dt, 0, 0.98);
    }

    if (t >= 1.05) {
      setStage("explode", now);
    }
  } else if (stage === "explode") {
    const t = (now - stageStartedAt) / 850;
    const drag = 0.965;

    for (const p of particles) {
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vx *= drag;
      p.vy *= drag;
      p.a = clamp(p.a - 0.014 * dt, 0, 0.98);
    }

    if (t >= 1.0) {
      setStage("assembleText", now);
    }
  } else if (stage === "assembleText") {
    const t = (now - stageStartedAt) / 1900;
    const k = 0.017 + 0.018 * easeOutCubic(t);
    const drag = 0.74;
    const layout = getTextLayout();

    for (let i = 0; i < particles.length; i++) {
      const p = particles[i];
      const target = textPoints[i % textPoints.length];
      const mapped = mapPointToCanvas(target, textModelWidth, textModelHeight, layout.scale, layout.cx, layout.cy);

      const dx = mapped.x - p.x;
      const dy = mapped.y - p.y;
      p.vx = p.vx * drag + dx * k;
      p.vy = p.vy * drag + dy * k;
      p.x += p.vx * dt;
      p.y += p.vy * dt;

      p.r = target.r;
      p.g = target.g;
      p.b = target.b;
      p.a = clamp(p.a + 0.035 * dt, 0.2, 0.98);
    }

    if (t >= 1.0 && !doneSignaled) {
      doneSignaled = true;
      setTimeout(() => {
        if (window.AndroidSplash && typeof window.AndroidSplash.onDone === "function") {
          window.AndroidSplash.onDone();
        }
      }, 700);
    }
  }

  for (const p of particles) {
    ctx.fillStyle = `rgba(${p.r}, ${p.g}, ${p.b}, ${p.a})`;
    ctx.fillRect(p.x, p.y, p.size, p.size);
  }

  requestAnimationFrame(loop);
}

window.Splash = {
  start: () => {
    startRequested = true;
    if (model && rocketPoints.length > 0) {
      internalStart();
    }
  }
};

if (model && rocketPoints.length > 0 && startRequested) {
  internalStart();
}
